def evict_kv_cache(cache: list, window: int) -> list:
    """Keep only the most recent `window` cache entries, evicting older ones."""
    if window <= 0:
        return []
    if len(cache) <= window:
        return cache
    return cache[-window:]

print(evict_kv_cache([1, 2, 3, 4, 5, 6], 3))
